mapper.select:
select  from breeding_cycles
where house_id = #{houseId} and id = #{id}
limit 1

select  from breeding_cycles
where house_id = #{houseId} and id = #{id}
limit 1 for update

select  from breeding_cycles
where house_id = #{houseId}
  and mother_rabbit_id = #{motherRabbitId}
  and lifecycle = 'OPEN'
order by id

mapper.update:
update breeding_cycles set stage = #{cycle.stage}, stage_entered_at = #{cycle.stageEnteredAt}, lifecycle = #{cycle.lifecycle}, result = #{cycle.result}, mating_method = #{cycle.matingMethod},
male_rabbit_id = ifnull(#{cycle.maleRabbitId}, male_rabbit_id), mating_date = #{cycle.matingDate}, pregnancy_check_date = #{cycle.pregnancyCheckDate}, pregnancy_result = #{cycle.pregnancyResult}, expected_birth_date = #{cycle.expectedBirthDate}, birth_date = #{cycle.birthDate}, weaning_date = #{cycle.weaningDate}, closed_at = #{cycle.closedAt}, close_reason = #{cycle.closeReason}, remark = #{cycle.remark},
total_kits = ifnull(#{cycle.totalKits}, total_kits), live_kits = ifnull(#{cycle.liveKits}, live_kits), current_nursing_kits = ifnull(#{cycle.currentNursingKits}, current_nursing_kits), weaned_kits = ifnull(#{cycle.weanedKits}, weaned_kits), avg_weaning_weight = #{cycle.avgWeaningWeight}, state_version = state_version + 1, update_by = #{cycle.updateBy}, update_time = now() where house_id = #{cycle.houseId} and id = #{cycle.id} and state_version = #{expectedVersion}

